'use strict';
/* pages.js: home, templates, lessons, games, pricing, dashboard, onboarding */
function allTemplates(){return [...TEMPLATES,...ME.custom.filter(c=>c.kind==='template').map(c=>({id:c._id,cat:c.cat,d:c.d,v:c.v|0||1,name:c.name,style:STYLE_NAMES[(c.v|0||1)-1],content:c.content,custom:1}))].filter(t=>!ME.hidden.includes(t.id)&&CATS.some(c=>c.id===t.cat))}
function allLessons(){return [...LESSONS,...ME.custom.filter(c=>c.kind==='lesson').map(c=>({...c.meta,id:c._id,c:c.content,custom:1}))].filter(l=>!ME.hidden.includes(l.id))}
const tplLocked=t=>allTemplates().filter(x=>x.cat===t.cat).indexOf(t)>=lim('tpl');
const lesLocked=l=>allLessons().indexOf(l)>=lim('lessons');
const tplSlides=t=>compose(t.cat,t.content,t.d,t.v);
const lesSlides=l=>compose('lesson',l.c,l.d,1);
const lockB=()=>`<span class="lockb">${ic('lock')}باقة أعلى</span>`;

/* ---------- onboarding: teacher account ---------- */
function onboard(){return new Promise(res=>{const d=openDialog(`<div class="onb">${mascot('gdn')}<div><h2 class="dh">أهلًا بكِ في مضبوط!</h2><p class="lead">أنشئي حسابك في دقيقة لتحفظي دروسك وألعابك وفصولك.${S.mode==='api'?' بياناتك محفوظة في حسابك على المنصة.':S.remote?' حسابك مرتبط بحسابك في Claude، فلا تحتاجين كلمة مرور.':' في هذه المعاينة تُحفظ بياناتك على هذا الجهاز.'}</p>
 <form class="onf"><label class="lab">اسمك كما سيظهر في الشهادات<input class="in" name="name" required maxlength="40" placeholder="أ. نورة"></label><label class="lab">المدرسة<input class="in" name="school" maxlength="60" placeholder="اختياري"></label><label class="lab">المرحلة<select class="in" name="stage"><option>رياض الأطفال</option><option>المرحلة الابتدائية</option><option>كلاهما</option></select></label><label class="lab">المواد التي تدرّسينها<input class="in" name="subjects" maxlength="80" placeholder="لغتي، الرياضيات…"></label><button class="btn pri">${ic('sparkles')}ابدئي رحلتك</button></form></div></div>`,{onClose:()=>res(false)});
 $('form',d).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);ME.p={name:String(f.get('name')).trim().slice(0,40),school:String(f.get('school')||'').slice(0,60),stage:String(f.get('stage')),subjects:String(f.get('subjects')||'').slice(0,80),plan:{id:'free'},payments:[],favs:[],history:[],created:new Date().toISOString()};
  const c=newClass('فصلي الأول');ME.classes=[c];ME.p.activeClass=c._id;try{await S.set(S.up(c._id),(({_id,...b})=>b)(c));await saveProfile()}catch(err){}d._onClose=null;d.remove();confetti(150);sfx('end');toast(`مرحبًا ${ME.p.name}!`);hdr();res(true)}})}
async function ensureMe(){if(!ME.ready)await loadMe();if(S.mode==='api'&&!S.signedIn){if(!await authDialog())return false;ME.ready=false;await loadMe();hdr()}if(!ME.p)return await onboard();return true}
function authDialog(mode='login'){return new Promise(res=>{const d=openDialog(`<div class="onb">${mascot('gdn')}<div><h2 class="dh">${mode==='login'?'تسجيل الدخول':'حساب جديد للمعلمة'}</h2><p class="lead">${mode==='login'?'أهلًا بعودتك! ادخلي ببريدك وكلمة المرور.':'أنشئي حسابك لتحفظي دروسك وألعابك وفصولك.'}</p>
 <form class="onf auf"><label class="lab">البريد الإلكتروني<input class="in" name="email" type="email" required autocomplete="email" dir="ltr"></label><label class="lab">كلمة المرور${mode==='login'?'':' (٨ أحرف على الأقل)'}<input class="in" name="password" type="password" required minlength="8" autocomplete="${mode==='login'?'current-password':'new-password'}" dir="ltr"></label><p class="aerr" role="alert"></p><button class="btn pri">${ic(mode==='login'?'log-in':'user-plus')}${mode==='login'?'دخول':'إنشاء الحساب'}</button></form>
 <p class="note">${mode==='login'?'ليس لديك حساب؟':'لديك حساب؟'} <button type="button" class="btn ter sm" data-swap>${mode==='login'?'أنشئي حسابًا جديدًا':'سجّلي الدخول'}</button></p></div></div>`,{onClose:()=>res(false)});
 $('[data-swap]',d).onclick=()=>{d._onClose=null;d.remove();authDialog(mode==='login'?'register':'login').then(res)};
 $('form',d).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),b=$('button.pri',d),er=$('.aerr',d);b.disabled=true;er.textContent='';
  try{const m=await S.call('POST','/api/'+(mode==='login'?'login':'register'),{email:String(f.get('email')).trim(),password:String(f.get('password'))});S.setMe(m);d._onClose=null;d.remove();res(true)}
  catch(err){b.disabled=false;er.textContent={bad_login:'البريد أو كلمة المرور غير صحيحة',exists:'هذا البريد مسجّل من قبل، سجّلي الدخول',weak_password:'كلمة المرور قصيرة، ٨ أحرف على الأقل',bad_email:'تأكدي من البريد الإلكتروني',too_many:'محاولات كثيرة، انتظري قليلًا ثم حاولي'}[err.code]||'تعذّر الاتصال، حاولي مرة أخرى'}}})}
async function logout(){try{await S.call('POST','/api/logout')}catch(e){}location.hash='home';location.reload()}

