function libCard(o){return `<article class="lc3"><button class="lc3t" ${o.open} aria-label="معاينة ${esc(o.title)}">${o.thumb}${o.lock?`<span class="lc3l">${ic('lock')}</span>`:''}${o.count?`<span class="lc3n">${o.count}</span>`:''}</button><div class="lc3b"><div class="lc3m">${o.meta||''}</div><h3>${esc(o.title)}</h3>${o.sub?`<p class="note">${o.sub}</p>`:''}</div><div class="lc3a">${o.acts}</div></article>`}
const TP={cat:'explain',q:'',d:''};
function vTemplates(){return `<section class="band"><div class="wrap"><div class="phead"><div><h1 class="h1s">مكتبة القوالب التعليمية</h1><p class="lead">اختاري قالبًا وعاينيه، ثم «استخدميه»: تكتبين محتواك فقط، والمنصة تضعه في أماكنه داخل التصميم.</p></div></div><div class="toolbar"><label class="srch">${ic('search')}<input class="in" type="search" data-tq value="${esc(TP.q)}" placeholder="ابحثي في كل القوالب: اسم القالب أو الفئة" aria-label="بحث في القوالب"></label><select class="in" data-td aria-label="العالم"><option value="">كل العوالم</option>${Object.entries(DESIGNS).map(([k,d])=>`<option value="${k}" ${TP.d===k?'selected':''}>${esc(d.name)}</option>`).join('')}</select>${viewTgl()}</div>${tabsHTML('tp',CATS.map(c=>[c.id,c.name,c.icon]),TP.cat)}<div id="tpPanel" role="tabpanel"></div></div></section>`}
