const LP={stage:'kg',subj:'',sem:'',q:'',grade:'',unit:'',sort:''};
function vLessons(){return `<section class="band"><div class="wrap"><h1 class="h1s">مكتبة الدروس الجاهزة</h1><p class="lead">دروس كاملة من التهيئة حتى بطاقة الخروج: شرح، وتقويم قبلي وبنائي وختامي، وتعليم متمايز، وأنشطة وألعاب، وملاحظات للمعلمة على كل شريحة.</p><div class="toolbar">${tabsHTML('lp',[['kg','رياض الأطفال','baby'],['p','المرحلة الابتدائية','school']],LP.stage)}${viewTgl()}</div><div id="lpF"></div><div id="lpPanel" role="tabpanel"></div><p class="note">بُني المحتوى استرشادًا بموضوعات المناهج السعودية، ولا يُعدّ مطابقة رسمية قبل مراجعته مع كتاب الطالب ومصادره.</p></div></section>`}
function lpPanel(){const all=allLessons().filter(l=>l.stage===LP.stage),subs=[...new Set(all.map(l=>l.subj))],sems=[...new Set(all.map(l=>l.sem))],grades=[...new Set(all.map(l=>l.grade))],units=[...new Set(all.filter(l=>!LP.subj||l.subj===LP.subj).map(l=>l.unit).filter(Boolean))];
 $('#lpF').innerHTML=`<div class="filters">${grades.length>1?`<label class="lab inl">الصف<select class="in" data-lf="grade"><option value="">الكل</option>${grades.map(s=>`<option ${LP.grade===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label>`:''}<label class="lab inl">الوحدة<select class="in" data-lf="unit"><option value="">الكل</option>${units.map(s=>`<option ${LP.unit===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label class="lab inl">الترتيب<select class="in" data-lf="sort"><option value="">الافتراضي</option><option value="az" ${LP.sort==='az'?'selected':''}>أبجديًا</option><option value="subj" ${LP.sort==='subj'?'selected':''}>حسب المادة</option></select></label><label class="lab inl">المادة<select class="in" data-lf="subj"><option value="">الكل</option>${subs.map(s=>`<option ${LP.subj===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label class="lab inl">الفصل الدراسي<select class="in" data-lf="sem"><option value="">الكل</option>${sems.map(s=>`<option ${LP.sem===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label class="lab inl grow">بحث<input class="in" data-lf="q" value="${esc(LP.q)}" placeholder="اسم الدرس أو الوحدة"></label></div>`;
 const ls=all.filter(l=>(!LP.subj||l.subj===LP.subj)&&(!LP.sem||l.sem===LP.sem)&&(!LP.grade||l.grade===LP.grade)&&(!LP.unit||l.unit===LP.unit)&&(!LP.q||(l.c.title+' '+l.unit+' '+l.subj).includes(LP.q.trim())));if(LP.sort==='az')ls.sort((a,b)=>a.c.title.localeCompare(b.c.title,'ar'));if(LP.sort==='subj')ls.sort((a,b)=>a.subj.localeCompare(b.subj,'ar'));const p=$('#lpPanel');
 if(!ls.length){p.innerHTML=`<div class="empty sm">${ic('search-x')}<h3>لا توجد دروس بهذه التصفية</h3><p class="note">غيّري المادة أو الوحدة، أو امسحي البحث.</p><button class="btn sec" data-lclear>مسح التصفية</button></div>`;icons();return}
 if(LIBV==='grid'){p.innerHTML=`<p class="note">${ar(ls.length)} درسًا</p><div class="lgrid3">${ls.map(l=>{const lk=lesLocked(l),sl=lesSlides(l);return libCard({title:l.c.title,open:`data-prevl="${esc(l.id)}"`,thumb:thumb(sl[0]),lock:lk,count:`${ar(sl.length)} شريحة`,meta:`<span class="bd y">${esc(l.grade)}</span><span class="bd">${esc(l.subj)}</span>`,sub:`الوحدة: ${esc(l.unit)} · ${esc(l.sem)} · درس كامل بأنشطة تفاعلية`,acts:`<button class="btn pri sm" data-playl="${esc(l.id)}">${ic('play')}اعرضي الدرس</button><button class="btn sec sm" data-prevl="${esc(l.id)}">${ic('gallery-horizontal')}الشرائح</button><button class="btn sec sm" data-jl="${esc(l.id)}">${ic('map')}رحلة تفاعلية</button>`})}).join('')}</div>`;icons();return}
 p.innerHTML=gallery('lpG',ls.map(l=>{const lk=lesLocked(l),n=lesSlides(l).length;return{slide:lesSlides(l)[0],label:l.c.title,cap:`<div class="cap"><div><h3>${esc(l.c.title)}</h3><div class="tags"><span class="bd y">${esc(l.grade)}</span><span class="bd">${esc(l.subj)}</span><span class="bd">الوحدة: ${esc(l.unit)}</span><span class="bd">${esc(l.sem)}</span><span class="bd">${ar(n)} شريحة</span>${lk?lockB():''}</div></div><div class="acts"><button class="btn sec" data-prevl="${esc(l.id)}">${ic('gallery-horizontal')}الشرائح</button><button class="btn sec" data-jl="${esc(l.id)}">${ic('map')}رحلة تفاعلية</button><button class="btn sec" data-editl="${esc(l.id)}">${ic('pencil')}عدّليه</button><button class="btn pri" data-playl="${esc(l.id)}">${ic('play')}اعرضي</button></div></div>`}}),{label:'الدروس'});icons();initGals(p)}
const findLes=id=>allLessons().find(l=>l.id===id);
function playLesson(id){const l=findLes(id);if(!l)return;if(lesLocked(l))return needPlan('هذا الدرس ضمن الباقة الاحترافية');openPlayer(lesSlides(l),l.c.title)}
async function editLesson(id){const l=findLes(id);if(!l)return;if(lesLocked(l))return needPlan('هذا الدرس ضمن الباقة الاحترافية');if(!await ensureMe())return;openStudio(newLesson({title:l.c.title,d:l.d,slides:lesSlides(l),src:'lesson:'+l.id,content:clone(l.c),cat:'lesson'}),true)}

/* ---------- games ---------- */
const GP={tab:'all',cat:''};
const GCATS=[['','الكل','sparkles'],['quiz','أسئلة وتحديات','circle-help',['wheel','boxes','star','catch','speed','balloons','tf','bank','teams','whoami']],['mem','ذاكرة ومطابقة','layers',['memory','match','drag']],['ord','ترتيب وتركيب','puzzle',['order','puzzle']],['adv','مغامرة واستكشاف','map',['treasure','hunt','maze']]];
function vGames(){return `<section class="band hero2 w-adv"><div class="wrap"><div class="h2row"><div><span class="bd y">مجموعة ألعاب تعليمية تفاعلية</span><h1 class="h1s">خلي دروسك مليانة حماس ومتعة!</h1><p class="lead">ألعاب بتصاميم أجواء المغامرات والعوالم الخيالية، برسومات أصلية مبهجة. أدخلي أسئلتك وإجاباتها واربطيها بدرسك خلال دقائق.</p></div><div class="h2art">${gameArt('balloons')}</div></div><div class="toolbar">${tabsHTML('gp',[['all','كل الألعاب','gamepad-2'],['mine','ألعابي','folder-heart']],GP.tab)}${viewTgl()}</div><div class="chips strip gcats" role="group" aria-label="تصنيف الألعاب">${GCATS.map(([k,l,i])=>`<button class="chip" data-gcat="${k}" aria-pressed="${GP.cat===k}">${ic(i)}${l}</button>`).join('')}</div><div id="gpPanel"></div></div></section>`}
function gpPanel(){const p=$('#gpPanel');
 const gc=GCATS.find(c=>c[0]===GP.cat),types=GT_ORDER.filter(t=>!gc||!gc[3]||gc[3].includes(t));$$('.gcats').forEach(x=>x.hidden=GP.tab!=='all');
 if(GP.tab==='all'&&LIBV==='grid'){p.innerHTML=`<div class="ggrid">${types.map(t=>{const g=allGames().find(x=>x.type===t&&!x.mine)||GAMES.find(x=>x.type===t),lk=gameLocked(t);return `<article class="gc3"><button class="gc3t" data-playg="${esc(g.id)}" aria-label="العبي ${esc(GTYPES[t].name)}">${gameArt(t)}${lk?`<span class="lc3l">${ic('lock')}</span>`:''}</button><div class="lc3b"><h3>${esc(GTYPES[t].name)}</h3><p class="note">${esc(GTYPES[t].desc)}</p></div><div class="lc3a"><button class="btn pri sm" data-playg="${esc(g.id)}">${ic('play')}جرّبي اللعبة</button><button class="btn sec sm" data-custom="${t}">${ic('pencil-ruler')}بأسئلتك</button></div></article>`}).join('')}</div>`;icons();return}
 if(GP.tab==='all'){p.innerHTML=gallery('gpG',types.map(t=>{const g=allGames().find(x=>x.type===t&&!x.mine)||GAMES.find(x=>x.type===t),lk=gameLocked(t);return{html:gameHero(g),th:gameArt(t),label:GTYPES[t].name,cap:`<div class="cap"><div><h3>${esc(GTYPES[t].name)}</h3><p class="note">${esc(GTYPES[t].desc)} · مثال: ${esc(g.title)}</p>${lk?lockB():''}</div><div class="acts"><button class="btn sec" data-custom="${t}">${ic('pencil-ruler')}خصّصيها بأسئلتك</button><button class="btn pri" data-playg="${esc(g.id)}">${ic('play')}العبي المثال</button></div></div>`}}),{label:'الألعاب'})}
 else{const mine=ME.games;p.innerHTML=mine.length?`<div class="mgrid">${mine.map(g=>`<article class="mgc">${gameArt(g.type)}<div><h3>${esc(g.title)}</h3><span class="bd">${esc(GTYPES[g.type]?GTYPES[g.type].name:'')}</span></div><div class="acts"><button class="btn pri sm" data-playg="${esc(g._id)}">${ic('play')}العبي</button><button class="btn sec sm" data-editg="${esc(g._id)}">${ic('pencil')}عدّلي</button><button class="ib" data-delg="${esc(g._id)}" aria-label="حذف اللعبة">${ic('trash-2')}</button></div></article>`).join('')}</div>`:`<div class="empty">${gameArt('boxes')}<h2>لا توجد ألعاب محفوظة بعد</h2><p class="lead">اختاري لعبة من «كل الألعاب» وخصّصيها بأسئلتك.</p></div>`}
 icons();initGals(p)}
async function gameEditor(type,existing){if(gameLocked(type))return needPlan('هذه اللعبة ضمن باقة أعلى');if(!await ensureMe())return;const T=GTYPES[type];
 const base=existing?clone(existing):clone(GAMES.find(g=>g.type===type));const cfg={...base,type,gtitle:existing?base.title:base.title+' (نسختي)'};cfg[T.f]=cfg[T.f]||[];
 const keys=['gtitle',T.f,'count',...(T.timed?['time']:[]),...(T.lvl?['level']:[]),...(T.ex||[])];
 const d=openDialog(`<h2 class="dh">${ic(T.icon)} ${esc(T.name)}: لعبتك بأسئلتك</h2><div class="gedit"><div id="geF"></div><div><div class="lab">تصميم اللعبة${designBtns(cfg.d||'adv','data-ged')}</div><div class="acts"><button class="btn sec" data-getry>${ic('play')}جرّبي</button><button class="btn pri" data-gesave>${ic('save')}احفظي في ألعابي</button></div><p class="note">يمكنك ربط اللعبة بأي عرض من الاستوديو، أو باختيارها في «لعبة مرتبطة بالدرس».</p></div></div>`,{wide:1,focus:false});
 bindForm($('#geF',d),keys,cfg,null);
 d.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.ged){cfg.d=b.dataset.ged;$$('[data-ged]',d).forEach(x=>{x.classList.toggle('on',x===b)})}
  const out=()=>{const o={type,title:(cfg.gtitle||T.name).slice(0,60),d:cfg.d||'adv',count:num(cfg.count)||8,time:num(cfg.time)||20,level:cfg.level||'all',[T.f]:cfg[T.f],updated:new Date().toISOString()};return o};
  if(b.hasAttribute('data-getry'))runGame({...out(),id:'preview'});
  if(b.hasAttribute('data-gesave')){const o=out(),id=existing?existing._id:'G_'+uid();try{await S.set(S.up(id),o);const k=ME.games.findIndex(x=>x._id===id);if(k>=0)ME.games[k]={...o,_id:id};else ME.games.unshift({...o,_id:id});closeDialog(d);toast('حُفظت اللعبة في «ألعابي»');GP.tab='mine';if(location.hash==='#games')route();regTeacher()}catch(err){toast('تعذّر الحفظ')}}})}

/* ---------- pricing & checkout ---------- */
const PR={cyc:'y'};
function planCards(cyc){const cur=curPlan().id;return `<div class="plans">${PLANS.map(p=>`<article class="plan ${p.hot?'hot':''} ${cur===p.id?'cur':''}">${p.hot?'<span class="bd y">الأكثر اختيارًا</span>':''}<h3>${esc(p.name)}</h3><p class="note">${esc(p.desc)}</p><div class="pnum">${p.m==null?'حسب الطلب':p.m===0?'مجانًا':`${ar(cyc==='y'?p.y:p.m)} <small>ريال / ${cyc==='y'?'سنة':'شهر'}</small>`}</div><ul class="ticks">${(p.feat||[]).map(tick).join('')}</ul>${cur===p.id?'<span class="btn sec" aria-disabled="true">باقتك الحالية</span>':p.id==='free'?'':p.m==null?`<button class="btn sec" data-school>${ic('building-2')}تواصلي معنا</button>`:`<button class="btn pri" data-buy="${p.id}">${ic('credit-card')}اشتركي</button>`}</article>`).join('')}</div>`}
function vPricing(){return `<section class="band"><div class="wrap"><h1 class="h1s">باقات الاشتراك</h1><p class="lead">اشتراك شهري أو سنوي. الأسعار تشمل كل المحتوى الجديد طوال مدة الاشتراك.</p><div class="chips cyc" role="group" aria-label="مدة الاشتراك"><button class="chip" data-cyc="m" aria-pressed="${PR.cyc==='m'}">شهري</button><button class="chip" data-cyc="y" aria-pressed="${PR.cyc==='y'}">سنوي · وفّري أكثر</button></div><div id="prCards">${planCards(PR.cyc)}</div><p class="note">الأسعار مقترحة للنموذج التجريبي، وتشمل ضريبة القيمة المضافة عند الدفع. يمكن تعديلها من لوحة الإدارة.</p></div></section>`}
async function checkout(id){if(!await ensureMe())return;const p=PLANS.find(x=>x.id===id),cyc=PR.cyc,base=cyc==='y'?p.y:p.m,vat=Math.round(base*.15*100)/100,tot=Math.round((base+vat)*100)/100;
 const d=openDialog(`<h2 class="dh">إتمام الاشتراك</h2><div class="chk"><div class="chkr"><span>الباقة</span><b>${esc(p.name)} · ${cyc==='y'?'سنوي':'شهري'}</b></div><div class="chkr"><span>السعر</span><b>${ar(base)} ريال</b></div><div class="chkr"><span>ضريبة القيمة المضافة ١٥٪</span><b>${ar(vat)} ريال</b></div><div class="chkr tot"><span>الإجمالي</span><b>${ar(tot)} ريال</b></div>
 <div class="lab">طريقة الدفع<div class="chips">${['مدى','Apple Pay','بطاقة ائتمانية','STC Pay'].map((m,i)=>`<button type="button" class="chip" data-pm aria-pressed="${i===0}">${m}</button>`).join('')}</div></div>
 <div class="demo">${ic('info')}<span>بوابة دفع تجريبية: لا تُطلب بيانات بطاقة ولا يُخصم أي مبلغ. الربط الفعلي مع بوابة دفع سعودية مثل ميسّر أو تاب أو HyperPay يتم في النسخة النهائية.</span></div><button class="btn pri" data-pay>${ic('lock')}إتمام الدفع التجريبي</button></div>`,{focus:false});
 d.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-pm')){$$('[data-pm]',d).forEach(x=>x.setAttribute('aria-pressed',x===b));return}
  if(b.hasAttribute('data-pay')){b.disabled=true;b.textContent='جارٍ المعالجة…';if(S.mode==='api'){try{ME.reg=await S.call('POST','/api/billing/demo',{plan:id,cycle:cyc})}catch(err){b.disabled=false;b.textContent='إتمام الدفع التجريبي';return toast(err.code==='payments_off'?'الدفع الإلكتروني لم يُفعّل بعد، تواصلي مع إدارة المنصة':'تعذّر إتمام العملية')}}else await new Promise(r=>setTimeout(r,900));const until=addDays(cyc==='y'?365:30);ME.p.plan={id,cycle:cyc,until,auto:true};(ME.p.payments=ME.p.payments||[]).unshift({id:'INV-'+Date.now().toString(36).toUpperCase(),date:today(),plan:p.name,cycle:cyc,amount:tot,vat,status:'تجريبي'});
   await saveProfile();closeDialog(d);confetti(200);sfx('end');toast(`فُعّلت ${p.name} حتى ${fmtDate(until)}`);hdr();route()}})}
