function lessonGrid(ls){return `<div class="lgrid2">${ls.map(l=>`<article class="lcard"><button class="lthumb" data-openl="${esc(l._id)}" aria-label="افتحي ${esc(l.title)}">${thumb((l.slides||[])[0])}</button><h3>${esc(l.title)}</h3><p class="note">${ar((l.slides||[]).length)} شرائح · ${esc(fmtDate(l.updated))}</p><div class="acts"><button class="btn pri sm" data-openl="${esc(l._id)}">${ic('pencil')}افتحي</button><button class="btn sec sm" data-playmine="${esc(l._id)}">${ic('play')}اعرضي</button>${l.content?`<button class="btn sec sm" data-jmine="${esc(l._id)}">${ic('map')}رحلة</button>`:''}<button class="ib" data-dupl="${esc(l._id)}" aria-label="تكرار">${ic('copy')}</button><button class="ib" data-dell="${esc(l._id)}" aria-label="حذف">${ic('trash-2')}</button></div></article>`).join('')}</div>`}
