 if(d.hd){HM.d=d.hd;$$('[data-hd]').forEach(x=>{x.classList.toggle('on',x===b);x.setAttribute('aria-pressed',x===b)});return paintHero()}
 if(d.tryt){const t=findTpl(d.tryt);if(t){if(tplLocked(t))return needPlan('هذا القالب ضمن الباقة الأساسية فما فوق');openPlayer(tplSlides(t),t.content.title)}return}
 if(d.usetpl)return useTemplate(d.usetpl);
 if(d.prevt){const t=findTpl(d.prevt);if(t)previewSlides(t.name,tplSlides(t),`<button class="btn pri" data-close data-usetpl2="${esc(t.id)}">${ic('wand-sparkles')}استخدميه</button>`).addEventListener('click',ev=>{const x=ev.target.closest('[data-usetpl2]');if(x)useTemplate(x.dataset.usetpl2)});return}
 if(d.fav){if(!await ensureMe())return;const f=ME.p.favs=ME.p.favs||[];const k=f.indexOf(d.fav);if(k>=0)f.splice(k,1);else f.push(d.fav);b.classList.toggle('on',k<0);toast(k<0?'أُضيف إلى المفضلة':'أُزيل من المفضلة');saveProfile();if(location.hash==='#dashboard')dbPanel();return}
 if(d.jl){const l=findLes(d.jl);if(!l)return;if(lesLocked(l))return needPlan('هذا الدرس ضمن الباقة الاحترافية');if(/^[a-z0-9-]+$/i.test(l.id)){const h='journey-'+l.id;if(location.hash==='#'+h)route();else location.hash=h}else openJourney(jSrcLesson(l));return}
 if(d.jmine){const l=ME.lessons.find(x=>x._id===d.jmine);if(l&&l.content)openJourney({id:l.id,title:l.title,c:l.content,d:l.d,subj:l.content.sub});return}
 if(d.playl)return playLesson(d.playl);if(d.editl)return editLesson(d.editl);
 if(d.prevl){const l=findLes(d.prevl);if(l){if(lesLocked(l))return needPlan('هذا الدرس ضمن الباقة الاحترافية');previewSlides(l.c.title,lesSlides(l))}return}
 if(d.playg)return openGameById(d.playg);
 if(d.custom)return gameEditor(d.custom);
 if(d.editg){const g=ME.games.find(x=>x._id===d.editg);if(g)gameEditor(g.type,g);return}
 if(d.delg){const g=ME.games.find(x=>x._id===d.delg);if(!g||!await confirmBox(`حذف لعبة «${g.title}» نهائيًا؟`,'احذفي'))return;await S.del(S.up(g._id));ME.games=ME.games.filter(x=>x!==g);toast('حُذفت اللعبة');return location.hash==='#games'?gpPanel():dbPanel()}
 if(d.buy)return checkout(d.buy);if(b.hasAttribute('data-school'))return schoolReq();
