 if(b.hasAttribute('data-newblank')){if(!await ensureMe())return;return openStudio(newLesson(),true)}
 if(b.hasAttribute('data-smart')){if(!await ensureMe())return;return smartDialog()}
 if(d.openl){const l=ME.lessons.find(x=>x._id===d.openl);if(l)openStudio(clone((({_id,...r})=>r)(l)));return}
 if(d.playmine){const l=ME.lessons.find(x=>x._id===d.playmine);if(l)openPlayer(l.slides,l.title);return}
